(async () => {
  const allEntries = { ...TAXON_MAPPING, ...BOTANICAL_TAXA };
  const uniqueQueries = [...new Set(Object.values(allEntries).map(v => v[0]))];
  console.log('Total unique scientific queries:', uniqueQueries.length);

  const cachePath = '/tmp/inat-taxa-photo-cache.json';
  const cache = fs.existsSync(cachePath) ? JSON.parse(fs.readFileSync(cachePath, 'utf8')) : {};

  let fetched = 0;
  for (let i = 0; i < uniqueQueries.length; i += 5) {
    const batch = uniqueQueries.slice(i, i + 5).filter(q => !cache[q]);
    if (batch.length === 0) continue;
    await Promise.all(batch.map(async (q) => {
      try {
        const res = await fetch(`https://api.inaturalist.org/v1/taxa?q=${encodeURIComponent(q)}&per_page=1`);
        if (res.ok) {
          const data = await res.json();
          const taxon = data.results?.[0];
          const photos = [];
          if (taxon?.default_photo?.medium_url) photos.push(taxon.default_photo.medium_url);
          if (Array.isArray(taxon?.taxon_photos)) {
            for (const tp of taxon.taxon_photos) {
              const u = tp?.photo?.medium_url;
              if (u && !photos.includes(u)) photos.push(u);
            }
          }
          if (photos.length > 0) {
            cache[q] = photos;
            fetched++;
          }
        }
      } catch (err) {
        // ignore transient error
      }
    }));
    await new Promise(r => setTimeout(r, 250));
  }

  fs.writeFileSync(cachePath, JSON.stringify(cache, null, 2));
  console.log('Cached taxa count:', Object.keys(cache).length, '(newly fetched:', fetched, ')');
})();
